    "testimonials.t3.quote": "मुझे पसंद है कि डॉक्टर के पर्चे की दवाएं ओटीसी से स्पष्ट रूप से अलग की गई हैं - यह डिफ़ॉल्ट रूप से रोगियों को सुरक्षित रखती हैं।",

    "firstaid.fever.title": "तेज बुखार",
    "firstaid.fever.desc": "103°F (39.4°C) से अधिक शरीर के तापमान पर तुरंत ध्यान देने की आवश्यकता है।",
    "firstaid.fever.step1": "अतिरिक्त कपड़े हटाएं और व्यक्ति को ठंडा रखें",
    "firstaid.fever.step2": "अनुशंसित खुराक के अनुसार पैरासिटामोल दें",
    "firstaid.fever.step3": "निर्जलीकरण को रोकने के लिए तरल पदार्थों को बढ़ावा दें",
    "firstaid.fever.step4": "यदि बुखार 2 दिनों से अधिक समय तक बना रहता है तो चिकित्सीय सहायता लें",
    "firstaid.heart-attack.title": "हार्ट अटैक",
    "firstaid.heart-attack.desc": "सीने में दर्द, सांस लेने में तकलीफ, या हाथ/जबड़े में दर्द।",
    "firstaid.heart-attack.step1": "तुरंत एम्बुलेंस (108) को कॉल करें",
    "firstaid.heart-attack.step2": "व्यक्ति को बैठाएं और शांत रखें",
    "firstaid.heart-attack.step3": "तंग कपड़े ढीले करें",
    "firstaid.heart-attack.step4": "एलर्जी न होने और सलाह मिलने पर ही एस्पिरिन दें",
    "firstaid.stroke.title": "स्ट्रोक / लकवा",
    "firstaid.stroke.desc": "अचानक सुन्नता, भ्रम, या बोलने में कठिनाई - तुरंत कार्रवाई करें।",
    "firstaid.stroke.step1": "लक्षण शुरू होने का समय नोट करें",
    "firstaid.stroke.step2": "तुरंत एम्बुलेंस को कॉल करें",
    "firstaid.stroke.step3": "व्यक्ति को सिर थोड़ा ऊपर उठाकर लिटाकर रखें",
    "firstaid.stroke.step4": "भोजन या पानी न दें",
    "firstaid.burns.title": "जलना (बर्न)",
    "firstaid.burns.desc": "त्वचा पर तापीय, रासायनिक या विद्युत जलन।",
    "firstaid.burns.step1": "10-15 मिनट के लिए बहते पानी के नीचे जलन को ठंडा करें",
    "firstaid.burns.step2": "बर्फ, मक्खन या मलहम न लगाएं",
    "firstaid.burns.step3": "स्टेरिल, नॉन-स्टिक ड्रेसिंग से ढीला ढकें",
    "firstaid.burns.step4": "हथेली से बड़े जलने के लिए चिकित्सीय सहायता लें",
    "firstaid.bleeding.title": "रक्तस्राव",
    "firstaid.bleeding.desc": "कट, घाव या चोट जिसके कारण खून बह रहा हो।",
    "firstaid.bleeding.step1": "साफ कपड़े से सीधा दबाव डालें",
    "firstaid.bleeding.step2": "यदि संभव हो तो घायल हिस्से को हृदय के स्तर से ऊपर उठाएं",
    "firstaid.bleeding.step3": "धंसी हुई वस्तुओं को न निकालें",
    "firstaid.bleeding.step4": "यदि 10 मिनट में रक्तस्राव न रुके तो चिकित्सीय सहायता लें",
    "firstaid.fracture.title": "अस्थि भंग (फैक्चर)",
    "firstaid.fracture.desc": "गिरने या चोट लगने से हड्डी टूटने का संदेह।",
    "firstaid.fracture.step1": "घायल हिस्से को स्थिर रखें - हिलने-डुलने से बचें",
    "firstaid.fracture.step2": "यदि प्रशिक्षित हैं तो स्प्लिंट से सहारा दें",
    "firstaid.fracture.step3": "सूजन कम करने के लिए कपड़े में लपेटी बर्फ लगाएं",
    "firstaid.fracture.step4": "एक्स-रे के लिए अस्पताल जाएं",
    "firstaid.snake-bite.title": "सर्पदंश (सांप का काटना)",
    "firstaid.snake-bite.desc": "विषैला या अज्ञात सांप का काटना जिसके लिए तत्काल देखभाल की आवश्यकता है।",
    "firstaid.snake-bite.step1": "व्यक्ति को शांत और स्थिर रखें",
    "firstaid.snake-bite.step2": "काटे गए अंग को हृदय के स्तर से नीचे स्थिर करें",
    "firstaid.snake-bite.step3": "घाव को काटें, चूसे या बर्फ न लगाएं",
    "firstaid.snake-bite.step4": "एंटीवेनम के लिए तुरंत अस्पताल जाएं",
    "firstaid.food-poisoning.title": "खाद्य विषाक्तता (फूड पॉइज़निंग)",
    "firstaid.food-poisoning.desc": "दूषित भोजन खाने के बाद मतली, उल्टी या दस्त।",
    "firstaid.food-poisoning.step1": "ओआरएस या सादे तरल पदार्थों के साथ हाइड्रेटेड रहें",
    "firstaid.food-poisoning.step2": "लक्षण कम होने तक आराम करें और ठोस भोजन से बचें",
    "firstaid.food-poisoning.step3": "चिकित्सीय सलाह के बिना दस्त-रोधी दवा से बचें",
    "firstaid.food-poisoning.step4": "खून, तेज बुखार या गंभीर निर्जलीकरण होने पर मदद लें",
    "firstaid.allergic-reaction.title": "एलर्जी की प्रतिक्रिया",
    "firstaid.allergic-reaction.desc": "एलर्जन के संपर्क में आने के बाद सूजन, दाने या सांस लेने में तकलीफ।",
    "firstaid.allergic-reaction.step1": "व्यक्ति को एलर्जन के स्रोत से दूर करें",
    "firstaid.allergic-reaction.step2": "यदि हल्का हो और उपलब्ध हो तो एंटीहिस्टामाइन दें",
    "firstaid.allergic-reaction.step3": "सांस लेने में तकलीफ या चेहरे पर सूजन होने पर तुरंत 108 पर कॉल करें",
    "firstaid.allergic-reaction.step4": "यदि निर्धारित और उपलब्ध हो तो एपिनेफ्रिन ऑटो-इंजेक्टर का उपयोग करें",
    "firstaid.choking.title": "दम घुटना / गले में अटकना",
    "firstaid.choking.desc": "भोजन या किसी वस्तु से श्वास नली अवरुद्ध होना - व्यक्ति सांस या बोल नहीं सकता।",
    "firstaid.choking.step1": "यदि व्यक्ति अभी भी सांस ले सकता है तो खांसने के लिए प्रोत्साहित करें",
