    "emergency.safety.Call emergency services immediately if symptoms become severe.": "அறிகுறிகள் தீவிரமடைந்தால் உடனடியாக அவசர சேவைகளை அழைக்கவும்.",
    "emergency.safety.Keep emergency numbers accessible at all times.": "அவசர எண்களை எப்போதும் பயன்படுத்தும் வகையில் வைத்திருக்கவும்.",
