    "firstaid.stroke.step4": "ఆహారం లేదా నీరు ఇవ్వవద్దు",
    "firstaid.burns.title": "కాలిన గాయాలు",
    "firstaid.burns.desc": "చర్మంపై ఉష్ణ, రసాయన లేదా విద్యుత్ కాలిన గాయాలు.",
    "firstaid.burns.step1": "10-15 నిమిషాల పాటు ప్రవహించే నీటి కింద గాయాన్ని చల్లబరచండి",
    "firstaid.burns.step2": "ఐస్, వెన్న లేదా లేపనాలు రాయవద్దు",
    "firstaid.burns.step3": "స్టెరైల్, నాన్-స్టిక్ డ్రెస్సింగ్‌తో వదులుగా కప్పండి",
    "firstaid.burns.step4": "అరచేతి కంటే పెద్ద కాలిన గాయాలకు వైద్య సహాయం తీసుకోండి",
    "firstaid.bleeding.title": "రక్తస్రావం",
    "firstaid.bleeding.desc": "రక్తస్రావం కలిగించే కోతలు లేదా గాయాలు.",
    "firstaid.bleeding.step1": "శుభ్రమైన గుడ్డతో నిలకడగా ఒత్తిడి నివ్వండి",
    "firstaid.bleeding.step2": "సాధ్యమైతే గాయపడిన ప్రాంతాన్ని గుండె మట్టం కంటే పైకి లేపండి",
    "firstaid.bleeding.step3": "గాయంలో గుచ్చుకున్న వస్తువులను తొలగించవద్దు",
    "firstaid.bleeding.step4": "10 నిమిషాల్లో రక్తస్రావం ఆగకపోతే వైద్య సహాయం తీసుకోండి",
    "firstaid.fracture.title": "ఎముక విరుపు",
    "firstaid.fracture.desc": "కిందపడటం లేదా దెబ్బ తగలడం వల్ల ఎముక విరిగినట్లు అనుమానం.",
    "firstaid.fracture.step1": "గాయపడిన ప్రాంతాన్ని నిలకడగా ఉంచండి - కదలికలను నివారించండి",
    "firstaid.fracture.step2": "శిక్షణ పొంది ఉంటే స్ప్లింట్‌తో మద్దతు ఇవ్వండి",
    "firstaid.fracture.step3": "వాపు తగ్గించడానికి గుడ్డలో చుట్టిన ఐస్ ఉంచండి",
    "firstaid.fracture.step4": "ఎక్స్-రే కోసం ఆసుపత్రికి వెళ్లండి",
    "firstaid.snake-bite.title": "పాము కాటు",
    "firstaid.snake-bite.desc": "తక్షణ సంరక్షణ అవసరమయ్యే విషపూరితమైన లేదా తెలియని పాము కాటు.",
    "firstaid.snake-bite.step1": "వ్యక్తిని ప్రశాంతంగా మరియు నిలకడగా ఉంచండి",
    "firstaid.snake-bite.step2": "కాటు వేసిన అవయవాన్ని గుండె మట్టం కంటే కిందకి నిలకడగా ఉంచండి",
    "firstaid.snake-bite.step3": "గాయాన్ని కోయడం, పీల్చడం లేదా ఐస్ పెట్టడం చేయవద్దు",
    "firstaid.snake-bite.step4": "యాంటీవెనమ్ కోసం వెంటనే ఆసుపత్రికి వెళ్లండి",
    "firstaid.food-poisoning.title": "ఫుడ్ పాయిజనింగ్",
    "firstaid.food-poisoning.desc": "కలుషితమైన ఆహారం తిన్న తర్వాత వికారం, వాంతులు లేదా విరేచనాలు.",
    "firstaid.food-poisoning.step1": "ORS లేదా ద్రవాలతో శరీరాన్ని రీహైడ్రేట్ చేయండి",
    "firstaid.food-poisoning.step2": "లక్షణాలు తగ్గే వరకు విశ్రాంతి తీసుకోండి మరియు ఘనమైన ఆహారాన్ని నివారించండి",
    "firstaid.food-poisoning.step3": "వైద్య సలహా లేకుండా విరేచనాల మందులు వాడవద్దు",
    "firstaid.food-poisoning.step4": "రక్తం, తీవ్రమైన జ్వరం లేదా డీహైడ్రేషన్ ఉంటే సహాయం కోరండి",
    "firstaid.allergic-reaction.title": "అలెర్జీ ప్రతిచర్య",
    "firstaid.allergic-reaction.desc": "అలెర్జెన్‌కు గురైన తర్వాత వాపు, దద్దుర్లు లేదా శ్వాస తీసుకోవడంలో ఇబ్బంది.",
    "firstaid.allergic-reaction.step1": "వ్యక్తిని అలెర్జెన్ మూలం నుండి తొలగించండి",
    "firstaid.allergic-reaction.step2": "సాధారణమైతే యాంటిహిస్టమైన్ ఇవ్వండి",
    "firstaid.allergic-reaction.step3": "శ్వాస తీసుకోవడంలో ఇబ్బంది లేదా ముఖం వాపు ఉంటే వెంటనే 108 కి కాల్ చేయండి",
    "firstaid.allergic-reaction.step4": "సూచించిన ఎపినెఫ్రిన్ ఆటో-ఇంజెక్టర్ ఉంటే ఉపయోగించండి",
    "firstaid.choking.title": "గొంతులో అడ్డుపడటం",
    "firstaid.choking.desc": "ఆహారం లేదా వస్తువు ద్వారా శ్వాసమార్గం అడ్డుపడటం - మాట్లాడటం లేదా శ్వాస తీసుకోలేకపోవడం.",
    "firstaid.choking.step1": "వ్యక్తి ఇంకా శ్వాస తీసుకోగలిగితే దగ్గమని చెప్పండి",
    "firstaid.choking.step2": "భుజాల మధ్య వెనుక భాగంలో 5 సార్లు తట్టండి",
    "firstaid.choking.step3": "5 పొత్తికడుపు ఒత్తిళ్లను (హీమ్‌లిచ్ యుక్తి) అనుసరించండి",
    "firstaid.choking.step4": "వస్తువు బయటకు రాకపోతే అత్యవసర సహాయం కోసం కాల్ చేయండి",
