    "emergency.safety.Do not self-medicate during serious emergencies.": "తీవ్ర ತುರ್ತು ಪರಿಸ್ಥಿತಿಗಳಲ್ಲಿ ಸ್ವಯಂ ಔಷಧಿ ತೆಗೆದುಕೊಳ್ಳಬೇಡಿ.",
