export function translate(langCode, key, params) {
  if (!key) return "";
  const code = langCode || "en";
  let str = translations[code]?.[key] ?? translations.en?.[key];

  if (!str) {
    // Prevent raw key display on screen e.g. "firstaid.fever.title" -> "High Fever" / humanized title
    const parts = key.split(".");
    const lastPart = parts[parts.length - 1];
    str = lastPart.replace(/([A-Z])/g, " $1").replace(/^./, (s) => s.toUpperCase());
  }

  if (code !== "en" && str) {
    str = formatMedicineText(str, code);
  }

  if (params && typeof params === "object") {
    Object.keys(params).forEach((paramKey) => {
      str = str.replace(new RegExp(`\\{${paramKey}\\}`, "g"), params[paramKey]);
    });
  }
  return str;
}
